DB_CHECK = r'''
import json, os, pathlib, subprocess, tempfile, unittest

BIN = pathlib.Path('/usr/lib/postgresql/17/bin')

class DbCheck(unittest.TestCase):
    def test_seeded(self):
        cluster = pathlib.Path(tempfile.gettempdir()) / 'cluster'
        cluster.mkdir(mode=0o700)
        data = cluster / 'data'
        env = {k: v for k, v in os.environ.items() if not
               (k.startswith('PG') or k.startswith('SUPABASE_DB_URL') or 'DSN' in k or 'DATABASE' in k)}
        def run(argv):
            result = subprocess.run(list(map(str, argv)), env=env, capture_output=True,
                                    text=True, timeout=30)
            self.assertEqual(result.returncode, 0, 'private PostgreSQL command failed')
            return result.stdout.strip()
        run([BIN / 'initdb', '-D', data, '-U', 'fixture', '--auth=trust', '-E', 'UTF8'])
        # Start the actual server at its canonical directory; the client keeps
        # its lexical application path, as in the relocated-root incident.
        try:
            run([BIN / 'pg_ctl', '-w', '-t', '15', '-D', data.resolve(), '-l', cluster / 'server.log',
                 '-o', '-F -c listen_addresses= -c port=55432 -c unix_socket_directories=' + str(cluster), 'start'])
            client = [BIN / 'psql', '-X', '-At', '-v', 'ON_ERROR_STOP=1', '-h', cluster,
                      '-p', '55432', '-U', 'fixture', '-d', 'postgres', '-c']
            run(client + ['CREATE TABLE seed(value integer); INSERT INTO seed VALUES (2205);'])
            self.assertEqual(run(client + ['SELECT value FROM seed']), '2205')
            observed = run(client + ['SHOW data_directory'])
            expected = str(data)
            print(json.dumps(dict(expected=expected, observed=observed, seed_readback=2205)), flush=True)
            self.assertEqual(expected, observed, 'canonical-data-directory')
        finally:
            subprocess.run([str(BIN / 'pg_ctl'), '-w', '-D', str(data.resolve()), '-m', 'immediate', 'stop'],
                           env=env, capture_output=True, timeout=20)

    def test_genuine_failure(self):
        self.assertEqual(1, 2, 'intentional-arithmetic')

if __name__ == '__main__':
    unittest.main(verbosity=2)
'''


class RunnerEnvironmentTests(unittest.TestCase):
    def test_ac1(self):
        rows = FROZEN["rows"]
        payload = json.loads(pathlib.Path(__file__).with_name(
            "runner_env_adr_payload.json").read_text())
        self.assertEqual(payload["cohort"], FROZEN["cohort"])
        self.assertEqual(len({r["source"] for r in rows}), len(rows))
        self.assertEqual(FROZEN["cohort"]["rejected_counted_type_rows_in_window"], 0)
        self.assertEqual(len(FROZEN["cohort"]["corrections"]), 3)
        for correction in FROZEN["cohort"]["corrections"]:
            self.assertNotIn(correction["target"], {r["source"] for r in rows})
            self.assertRegex(correction["source_sha256"], r"^[0-9a-f]{64}$")
        rejected = collections.defaultdict(list)
        for row in rows:
            self.assertTrue(FROZEN["cohort"]["start"] <= row["ts"] <= FROZEN["cohort"]["cutoff"])
            self.assertRegex(row["source_sha256"], r"^[0-9a-f]{64}$")
            self.assertTrue(row["subject"] and row["attempt"])
            if row["type"] == "rejected-criterion":
                rejected[row["subject"], row["attempt"]].append(row)
        verdicts = [r for r in rows if r["type"] == "verdict"]
        self.assertEqual(len({(r["subject"], r["attempt"]) for r in verdicts}), len(verdicts))
        failed = [r for r in verdicts if r["confirmed"] is False]
        for row in rows:
            observations = rejected[row["subject"], row["attempt"]] if row["type"] == "verdict" else [row]
            if row["type"] == "verdict" and row["confirmed"] is True:
                category, cause = "passed", "confirmed"
            elif any(r["features"]["alias"] for r in observations):
                category, cause = "runner-environment", "temporary-alias"
            elif any(r["features"]["assertion"] for r in observations):
                category, cause = "criterion-failure", "explicit-assertion-or-missing-implementation"
            else:
                category, cause = "unresolved", "insufficient-causal-evidence"
            self.assertEqual((row["classification"], row["cause"]), (category, cause))
        denominators = dict(verdict_references=len(verdicts), failed_grade_attempts=len(failed),
            passed_grade_attempts=sum(r["confirmed"] is True for r in verdicts),
            unknown_outcome=sum(r["confirmed"] not in (True, False) for r in verdicts),
            criterion_observations=sum(r["type"] == "rejected-criterion" for r in rows),
            setup_failures=sum(r["type"] == "evidence-bundle-failed" for r in rows),
            launch_failures=sum(r["type"] == "spawn-failed" for r in rows))
        self.assertEqual(payload["denominators"], denominators)
        self.assertEqual(denominators["verdict_references"], sum(denominators[k] for k in
            ("failed_grade_attempts", "passed_grade_attempts", "unknown_outcome")))
        counts = collections.Counter(r["cause"] for r in failed)
        ranking = [dict(cause=k, count=v, classification=next(r["classification"] for r in failed
            if r["cause"] == k)) for k, v in sorted(counts.items(), key=lambda x: (-x[1], x[0]))]
        self.assertEqual(payload["ranking"], ranking)
        self.assertEqual(sum(counts.values()), len(failed))
        projects = dict(collections.Counter(r["project"] for r in failed))
        self.assertEqual(payload["per_project"], projects)
        tables = {kind: dict(collections.Counter(r["classification"] for r in rows
            if r["type"] == kind)) for kind in
            ("rejected-criterion", "evidence-bundle-failed", "spawn-failed")}
        self.assertEqual(payload["observation_tables"], tables)
        self.assertTrue(any(len(rejected[r["subject"], r["attempt"]]) > 1 for r in failed))
        self.assertTrue(any(r["classification"] == "unresolved" for r in failed))
        self.assertEqual(payload["named_fixes"], [dict(cause="temporary-alias", regressions=[
            "RunnerEnvironmentTests.test_ac2", "RunnerEnvironmentTests.test_ac3", "RunnerEnvironmentTests.test_ac4"])])
        for fix in payload["named_fixes"]:
            for name in fix["regressions"]:
                self.assertTrue(callable(getattr(type(self), name.split(".")[-1])))
        evidence("AC1", dict(denominators=denominators, ranking=ranking, per_project=projects,
            source_rows=len(rows), observation_tables=tables,
            provenance="row-level ledger references and source hashes",
            attribution="conservative; unresolved diagnoses are not inferred from rejected counts"))

    def regression(self, cls, name):
        case = cls(name)
        try:
            case.setUp()
            getattr(case, name)()
        finally:
            case.doCleanups()

    def test_ac2(self):
        with contextlib.ExitStack() as stack:
            root = pathlib.Path(stack.enter_context(tempfile.TemporaryDirectory(
                prefix="rt-", dir="/var/tmp"))).resolve()
            stack.enter_context(patch.object(build_runner, "SHORT_TMP_BACKING_ROOT", root))
            parent = dict(os.environ)
            paths = []
            for _ in range(3):
                path = build_runner.short_tmpdir()
                paths.append(path)
                self.assertEqual(path, path.resolve())
                self.assertEqual(path.parent, root)
                self.assertFalse(path.is_symlink())
                self.assertEqual(stat.S_IMODE(path.stat().st_mode), 0o700)
                self.assertEqual(path.stat().st_uid, os.geteuid())
                child = path / ("s" * 20)
                child.mkdir()
                sockpath = child / ".s.PGSQL.65535"
                self.assertLess(len(os.fsencode(sockpath)), 107)
                with socket.socket(socket.AF_UNIX) as sock:
                    sock.bind(str(sockpath))
            self.assertEqual(len(set(paths)), 3)
            self.assertEqual(dict(os.environ), parent)
            long_root = root / ("x" * 100)
            long_root.mkdir()
            with patch.object(build_runner, "SHORT_TMP_BACKING_ROOT", long_root):
                with self.assertRaises(build_runner.Undetermined):
                    build_runner.short_tmpdir()
                tails = root / "tails"
                tails.mkdir()
                with patch.object(build_runner, "_provision") as provision:
                    with self.assertRaisesRegex(build_runner.Undetermined, "too long"):
                        build_runner._run_tree("L-spec-9000", "a" * 40, root, {},
                            [("AC1", "true")], tails, 0, 1000, time.monotonic() + 30)
                    provision.assert_not_called()
            self.assertEqual(list(long_root.iterdir()), [])
            alias = root / "linked-root"
            alias.symlink_to(root, target_is_directory=True)
            with patch.object(build_runner, "SHORT_TMP_BACKING_ROOT", alias):
                with self.assertRaisesRegex(build_runner.Undetermined, "symlinked"):
                    build_runner.short_tmpdir()
            evidence("AC2", dict(unique=3, canonical=True, socket_bind=True,
                                 long_root_refused=True, parent_unchanged=True))
        self.regression(runner_tests.ShortTmpdirTests, "test_ac1")
        self.regression(runner_tests.ShortTmpdirTests, "test_ac2")

    def test_ac3(self):
        self.assertTrue(pathlib.Path('/usr/lib/postgresql/17/bin/initdb').is_file(),
                        'real PostgreSQL tooling is required')
        self.assertEqual(INCIDENT_SOURCES[0]['source'], 'L-grader-5533.jsonl:7')
        for source in INCIDENT_SOURCES:
            self.assertRegex(source['source_sha256'], r'^[0-9a-f]{64}$')
        with contextlib.ExitStack() as stack:
            root = pathlib.Path(stack.enter_context(tempfile.TemporaryDirectory(
                prefix='pg-', dir='/var/tmp'))).resolve()
            repo = root / 'repo'
            repo.mkdir()
            env = {k: v for k, v in build_runner.grading_env._clean_env().items()
                   if not k.startswith('GIT_')}
            env.update(GIT_AUTHOR_NAME='fixture', GIT_AUTHOR_EMAIL='fixture@localhost',
                       GIT_COMMITTER_NAME='fixture', GIT_COMMITTER_EMAIL='fixture@localhost')
            def git(*args):
                return subprocess.run(['git', '-C', str(repo), *args], env=env,
                    capture_output=True, text=True, check=True).stdout.strip()
            git('init', '-q')
            (repo / 'db_check.py').write_text(DB_CHECK)
            git('add', 'db_check.py')
            git('commit', '-qm', 'seeded canonical-path database fixture')
            sha = git('rev-parse', 'HEAD')
            clean = root / 'clean'
            git('clone', '-q', str(repo), str(clean))
            self.assertEqual(subprocess.check_output(['git', '-C', str(clean), 'rev-parse', 'HEAD'],
                             env=env, text=True).strip(), sha)
            passing = '/usr/bin/python3 db_check.py DbCheck.test_seeded'
            failing = '/usr/bin/python3 db_check.py DbCheck.test_genuine_failure'
            matrix = {}
            for mode in ('clean', 'legacy'):
                canonical = root / (mode + '-tmp')
                canonical.mkdir()
                temporary = canonical
                if mode == 'legacy':
                    temporary = root / 'alias'
                    temporary.symlink_to(canonical, target_is_directory=True)
                child_env = dict(env, TMPDIR=str(temporary), TMP=str(temporary), TEMP=str(temporary))
                results = [subprocess.run(['/bin/bash', '-c', command], cwd=clean,
                    env=child_env, capture_output=True, text=True, timeout=60)
                    for command in (passing, failing)]
                self.assertEqual([r.returncode for r in results], [int(mode == 'legacy'), 1])
                self.assertIn('intentional-arithmetic', results[1].stderr)
                paths = json.loads(results[0].stdout.splitlines()[0])
                self.assertEqual(paths['seed_readback'], 2205)
                self.assertEqual(paths['expected'] == paths['observed'], mode == 'clean')
                if mode == 'legacy':
                    self.assertIn('canonical-data-directory', results[0].stderr)
                    self.assertIn('FAIL: test_seeded', results[0].stderr)
                matrix[mode] = dict(exits=[r.returncode for r in results], paths=paths)
            backing = root / 'b'
            backing.mkdir()
            legacy = root / 'legacy'
            legacy.mkdir()
            ledger = root / 'ledger'
            ledger.mkdir()
            def sub(name):
                path = root / 'scratch' / name
                path.mkdir(parents=True, exist_ok=True)
                return path
            stack.enter_context(patch.object(build_runner.scratch, 'sub', side_effect=sub))
            stack.enter_context(patch.object(build_runner.fold, 'ROOT', ledger))
            stack.enter_context(patch.multiple(build_runner, SHORT_TMP_ROOT=legacy,
                                               SHORT_TMP_BACKING_ROOT=backing))
            parent = dict(os.environ)
            for selection, commands, exits in (
                    ('full', [(None, passing), (None, failing)], [0, 1]),
                    ('selected-pass', [('AC1', passing)], [0]),
                    ('selected-fail', [('AC2', failing)], [1])):
                pairs = []
                for baseline in (False, True):
                    tails = root / (selection + ('-base' if baseline else '-tip'))
                    tails.mkdir()
                    result = build_runner._run_tree('L-spec-9000', sha, repo, {}, commands,
                        tails, 0, 65536, time.monotonic() + 120, baseline=baseline)
                    self.assertEqual([r['exit'] for r in result[0]], exits)
                    pairs.append(result)
                    outputs = [pathlib.Path(r['tail']).read_text() for r in result[0]]
                    key = selection + ('-base' if baseline else '-tip')
                    matrix[key] = dict(exits=exits, failing_ids=[r['failing_ids'] for r in result[0]])
                    if 0 in exits:
                        report = next(line for line in outputs[0].splitlines() if '{' in line)
                        paths = json.loads(report[report.index('{'):])
                        self.assertEqual(paths['expected'], paths['observed'])
                        self.assertEqual(paths['seed_readback'], 2205)
                        matrix[key]['paths'] = paths
                    if 1 in exits:
                        self.assertIn('intentional-arithmetic', outputs[-1])
                        self.assertTrue(result[0][-1]['failing_ids'])
                comparison = build_runner._compare('fixture', sha, pairs[0][0], pairs[1][0],
                    pairs[0][1], pairs[1][1], pairs[1][2])
                if 1 in exits:
                    self.assertTrue(comparison['pre_existing'], comparison)
                self.assertEqual(list(backing.iterdir()), [])
            self.assertEqual(dict(os.environ), parent)
            self.assertEqual(git('status', '--porcelain'), '')
            real_paths = [value['paths']['expected'] for key, value in matrix.items()
                          if key.startswith(('full-', 'selected-pass-'))]
            self.assertEqual(len(set(real_paths)), 4)
            evidence('AC3', dict(matrix=matrix, same_commit=True, unchanged_check_code=True,
                canonical_assertion_id='DbCheck.test_seeded:canonical-data-directory',
                genuine_failure_retained=True, incident_sources=INCIDENT_SOURCES))

    def test_ac4(self):
        self.regression(runner_tests.ShortTmpdirTests, "test_ac3")
        self.regression(runner_tests.ShortTmpdirTests, "test_ac4")
        with contextlib.ExitStack() as stack:
            root = pathlib.Path(stack.enter_context(tempfile.TemporaryDirectory(
                prefix="rt-", dir="/var/tmp"))).resolve()
            backing = root / "real"
            backing.mkdir()
            legacy = root / "legacy"
            legacy.mkdir()
            proc = root / "proc"
            (proc / "net").mkdir(parents=True)
            (proc / "net/unix").write_text("header\n")
            allocation = backing / "dr-2147483647-01234567"
            allocation.mkdir(mode=0o700)
            marker = root / "marker"
            marker.write_text("keep")
            (allocation / "nested").symlink_to(marker)
            result = build_runner.sweep_short_tmpdirs(legacy, backing_root=backing, proc_root=proc)
            self.assertEqual(result, dict(removed=1, retained=0, errors=0))
            self.assertEqual(marker.read_text(), "keep")
            allocation.mkdir(mode=0o700)
            identity = build_runner._tmp_pair(allocation, allocation)
            moved = allocation.with_name("held")
            allocation.rename(moved)
            allocation.mkdir(mode=0o700)
            with self.assertRaisesRegex(OSError, "changed"):
                build_runner._remove_tmp_pair(allocation, allocation, identity)
            self.assertTrue(allocation.exists() and moved.exists())
            link = root / "linked"
            link.symlink_to(backing, target_is_directory=True)
            self.assertEqual(build_runner.sweep_short_tmpdirs(legacy, backing_root=link,
                             proc_root=proc), dict(removed=0, retained=0, errors=1))
            evidence("AC4", dict(real_orphan=result, changed_identity_retained=True,
                                 symlinked_discovery_retained=True, nested_target_retained=True))

    def test_ac5(self):
        self.regression(runner_tests.BuildRunnerTests, "test_roundtrip_event_foreign_ledger_env_digest_matches_file")
        self.regression(runner_tests.BuildRunnerTests, "test_bundle_reuse_publication_retry_review_and_forced_execution")
        case = runner_tests.BuildRunnerTests("test_env_none_row")
        try:
            case.setUp()
            bundle, path = case.bundle()
            self.assertEqual(bundle["runner_version"], build_runner.VERSION)
            # Keep all other cache inputs and the recorded content digest valid.
            # An actual old-version bundle must be rejected for version alone.
            bundle["runner_version"] = "2"
            data = (json.dumps(bundle, indent=2) + "\n").encode()
            path.write_bytes(data)
            ledger = case.root / "events/L-build-runner-local.jsonl"
            rows = [json.loads(line) for line in ledger.read_text().splitlines()]
            rows[-1]["bundle_sha256"] = hashlib.sha256(data).hexdigest()
            ledger.write_text("".join(json.dumps(row) + "\n" for row in rows))
            fresh, fresh_path = case.bundle()
            self.assertNotEqual(fresh_path, path)
            self.assertEqual(fresh["runner_version"], build_runner.VERSION)
            reused, reused_path = case.bundle()
            self.assertEqual(reused_path, fresh_path)
            self.assertEqual(reused["invocation_id"], fresh["invocation_id"])
            evidence("AC5", dict(real_roundtrip=True, fresh_process_fold=True,
                                 old_version_rejected=True, current_version_reused=True))
        finally:
            case.doCleanups()


if __name__ == "__main__":
    unittest.main(verbosity=2)
